INSERT dbo.PM_ForecastOrderActual(CorpId,CustCode,ItemCode,ChannelName,ItemName,OrderDate,OrderQty)
SELECT '1000',s.CustCode,s.ItemCode,c.CustName,i.ItemName,s.OrderDate,s.OrderQty
FROM @Source s JOIN CM_Cust c ON c.CorpId='1000' AND c.CustCode=s.CustCode
JOIN CM_Item i ON i.CorpId='1000' AND i.ItemCode=s.ItemCode
WHERE NOT EXISTS(SELECT 1 FROM PM_ForecastOrderActual a WITH(UPDLOCK,HOLDLOCK) WHERE a.CorpId='1000' AND a.CustCode=s.CustCode AND a.ItemCode=s.ItemCode AND a.OrderDate=s.OrderDate);
SELECT @@ROWCOUNT AS AddedActualRows;
DECLARE @Pairs TABLE(CustCode nvarchar(20),ItemCode nvarchar(200),PRIMARY KEY(CustCode,ItemCode));
