INSERT CM_ItemPrice(CorpId,CustCode,ItemCode,PriceType,Price,ApplyDate,ChannelName,ForecastItemName,UseYn,CreId,CreDt)
SELECT '1000',s.CustCode,s.ItemCode,'20',NULL,CONVERT(date,GETDATE()),c.CustName,i.ItemName,'Y',N'개발자',GETDATE()
FROM @Pairs s JOIN CM_Cust c ON c.CorpId='1000' AND c.CustCode=s.CustCode
JOIN CM_Item i ON i.CorpId='1000' AND i.ItemCode=s.ItemCode
WHERE NOT EXISTS(SELECT 1 FROM CM_ItemPrice p WHERE p.CorpId='1000' AND p.CustCode=s.CustCode AND p.ItemCode=s.ItemCode AND p.PriceType='20');
SELECT @@ROWCOUNT AS AddedCustomerItems;
COMMIT;
